export const getVisibleSessions = (
    sessions: DropdownSession[],
    currentSessionId: string,
    maxVisible = 7
): DropdownSession[] => {
    if (!sessions.length) return [];
    const currentIndex = sessions.findIndex(session => session.id === currentSessionId);
    if (currentIndex === -1) return sessions.slice(0, maxVisible);

    const beforeCount = Math.floor((maxVisible - 1) / 2);
    const afterCount = maxVisible - beforeCount - 1;
    let startIndex = Math.max(0, currentIndex - beforeCount);
    let endIndex = Math.min(sessions.length - 1, currentIndex + afterCount);

    // Adjust window if near start/end
    if (currentIndex < beforeCount) endIndex = Math.min(sessions.length - 1, maxVisible - 1);
    if (currentIndex > sessions.length - afterCount - 1) startIndex = Math.max(0, sessions.length - maxVisible);

    return sessions.slice(startIndex, endIndex + 1);
};
