export const getSessionStatus = (
    status: boolean, 
    idx: number, 
    isAIAnalyzed: boolean | undefined,
    activeSessionId: string,
    sessionId: string,
    hasVideo: boolean
): [AvatarIcon, React.ReactElement] => {
    if(!hasVideo) {
        return ["noVideo", <NoVideoIcon />];
    } 
    if(isAIAnalyzed) {
        if(status && activeSessionId === sessionId) return ['ai-pause', <AIPauseSVG/>];
        return ['ai-play', <AIPlaySVG/>];
    }
    if(status && activeSessionId === sessionId) return ['pause', <PauseBlueVideoIcon />];
    return ['play', <PlayBlueVideoIcon />];
};

export const formatDuration = (duration: string) => duration.split('.')[0];

export const formatSessionDate = (date: string) =>
    date ? format(new Date(date), "dd MMM yyyy, hh:mm a") : "--";
export const getUserNameConfig = (user: UserProperty) => {
    const userName = {
        content: '',
        tooltip: null as React.ReactNode,
    }
    if ( user?.kUXCam_UserIdentity ) {
        userName.content = user?.kUXCam_UserIdentity;
        return userName;
    }
    userName.content = `${user?.uxcamuserid} *`;
    userName.tooltip = "Custom user ID was not set for this user."
    return userName;
}
export const getUserName = (user: UserProperty) => {
    return (
        <Tooltip
            title={getUserNameConfig(user).tooltip}>
            <UserName italic={!!getUserNameConfig(user).tooltip}>
                {getUserNameConfig(user).content}
            </UserName>
        </Tooltip>
    );
};

const options = {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
} as Intl.DateTimeFormatOptions;

export const convertDecimalToTime = (decimalHours: number) => {
    const isNegative = decimalHours < 0;
    const hours = Math.floor(decimalHours);
    const minutes = Math.round((decimalHours - hours) * 60);
    return `${isNegative ? '-' : '+'}${hours}:${minutes.toString().padStart(2, '0')}`;
};

export const getTimeDuration = (
    deviceLocalDateTime: string,
    userTimezone: string
) => {
    const localDate = new Date(deviceLocalDateTime);
    const formattedDateTime = new Intl.DateTimeFormat('en-US', options).format(localDate);
    return [`${formattedDateTime} (UTC ${userTimezone})`,
        formattedDateTime,
        `(UTC ${userTimezone})`
    ];
}; 


