export const trackAISessionSelect = ({
    sessionId,
    aiAnalyzed,
    filtersApplied,
    duration,
    containsVideo,
    gestureCount,
    sessionSelectedFrom,
    parentType,
    isCrashed,
    isRageTap,
    isUiFreeze
}: {
    sessionId: string,
    filtersApplied: any,
    aiAnalyzed: boolean,
    duration: number,
    containsVideo: boolean,
    gestureCount: number,
    sessionSelectedFrom: 'user_playlist' | 'session_playlist' | 'list' | 'tara',
    parentType: string,
    isRageTap: boolean,
    isUiFreeze: boolean,
    isCrashed: boolean
}) => {
    const frustrations = [
        isRageTap && 'rage_tap',
        isUiFreeze && 'ui_freeze',
        isCrashed && 'crashed'
    ].filter(Boolean);

    return trackPageViews(null, {
        eventName: 'wa_sessions_visit_session_player',
        track_type: 'event',
        pageName: parentType,
        eventProperty: {
            session_id: sessionId,
            filters_applied: filtersApplied ? removeValuesFromFilters(filtersApplied) : null,
            ai_analyzed: aiAnalyzed,
            duration,
            contains_video: containsVideo,
            gesture_count: gestureCount,
            frustrations, 
            session_selected_from: sessionSelectedFrom,
        },
    })
}

