const IssueInfo = ({ isCrashLog, totalBugs, anrMenu }) => {
  const containerRef = useRef()
  const { setSelectedHeaderField } = useSessionHeader();
    const { rewind } = useSessionTimeLine();
    const handleRewind = (e,time) => {
        e.preventDefault()
        e.stopPropagation();
        rewind(time)
    }
  const handleMenuChange = (value) => {
    setSelectedHeaderField(value);
  }

  const getMilliSecondsPad = useCallback((num, size) => (`000${  num}`).slice(size * -1), []);

  const displayTime = useCallback((timeInSeconds) => {
    const hmsFormat = getTimeDuration(timeInSeconds);
    const milliseconds = parseFloat(timeInSeconds).toFixed(1).slice(-1);
    return `${hmsFormat  }.${  getMilliSecondsPad(milliseconds, 1)}`
  }, [])

  const uiFreezeMenu = useMemo(() => (
    <IssueInfoMenu onClick={(e) => handleMenuChange(e.key)}>
      {anrMenu.map((anr, index) => <IssueInfoMenuItem key={`UIFreeze_${anr?.params?.anrNumber}`}>
        <span><AnrInfo
                time={anr?.time}
                duration={anr?.params?.duration}
                displayTime={displayTime}
                params={anr?.params}
                dataLength={anrMenu?.length - index === 0}
                handleRewind={handleRewind}/></span>
      </IssueInfoMenuItem>)}
    </IssueInfoMenu>), [anrMenu])

  const bugsMenu = useMemo(
    () => (
      <IssueInfoMenu onClick={(e) => handleMenuChange(e.key)}>
        {totalBugs.map((bug, index) => (
          <IssueInfoMenuItem key={`exception_${bug?.timeFromStart}+${index}`}>
            <span>
              <AnrExceptionInfo
                title={bug?.exceptionName}
                time={bug?.timeFromStart}
                displayTime={displayTime}
                reason={bug?.reason}
                dataLength={totalBugs?.length - index === 0}
                handleRewind={handleRewind}
              />
            </span>
          </IssueInfoMenuItem>
        ))}
      </IssueInfoMenu>
    ),
    [totalBugs]
  );

  const handleGetContainer = React.useCallback( () => containerRef.current, [ containerRef ] )

  return (
    <Wrapper ref={ containerRef }>
      {isCrashLog ? <CrashedButton  value={anrMenu?.length > 0 || totalBugs?.length > 0} onClick={() => setSelectedHeaderField('crash')}><AppCrashIcon />Crashed</CrashedButton> : null}
      {anrMenu instanceof Array &&
        anrMenu.length > 0 ? <Dropdown getPopupContainer={ handleGetContainer } overlay={uiFreezeMenu}>
          <StyledDiv value={ totalBugs?.length > 0 } type='text'><span><UIFreezeSvg /></span>{`${anrMenu.length} UI freeze${anrMenu?.length > 1 ? 's' :''}`} <DownOutlined/>
          </StyledDiv></Dropdown> : null}
      {totalBugs &&
        totalBugs.length > 0 ?
      <Dropdown getPopupContainer={ handleGetContainer } overlay={bugsMenu}><div type='text'><span><BugIconSVG /></span>{`${totalBugs.length} Exception${totalBugs?.length > 1 ? 's': ''}`} <DownOutlined/></div></Dropdown> : null}
    </Wrapper>
  );
};

