export const AnrInfo = ({ time, duration, params, dataLength, handleRewind }) => (
    <AnrInfoDropdown isMultiple={ dataLength }>
        <div className="content-wrap">
            <span className="duration">
      <span className="screen">{`${parseFloat(duration).toFixed(0)}s in ${params?.screen}`}</span>
      <span className="topofstack">{params?.topOfStack}</span>
    </span>
        </div>
            <span aria-hidden='true' className='time-btn' onClick={(e)=> handleRewind(e,time)}><VideoIcon/> {secondsToTime(time)}</span>
    </AnrInfoDropdown>
);

export const AnrExceptionInfo = ({
  title,
  time,
  reason,
  dataLength,
  handleRewind,
}) => (
  <AnrExceptionInfoDropdown isMultiple={dataLength}>
    <div className="content-wrap">
      <span className="title">
        <Tooltip title={title}>
          <p>{`${title}`}</p>
        </Tooltip>
        <span
          aria-hidden="true"
          className="time-btn"
          onClick={(e) => handleRewind(e, time)}
        >
          <VideoIcon /> {time < 60 ? `${time}s` : secondsToTime(time)}
        </span>
      </span>
    </div>
    <span className="reason"> {`${reason}`}</span>
  </AnrExceptionInfoDropdown>
);
