/* eslint-disable react/no-array-index-key */
import React, { memo, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { contains } from 'underscore';
import { useQueryClient } from 'react-query';

import CommonCustomLabel from 'components/common/DetailPageCustomLabel';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';
import { trackPageViews } from 'redux/actions/trackingReport';
import { getAIDetailsKey } from 'components/features/aiSessions/components/utils';

import uniq from 'lodash/uniq';
import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';

const EnabledSessionLabelParentTypes = ['sessionsList', 'aiSessionsList', 'eventsList', 'issues', 'heatmapsList'];

const SessionCustomLabels = ({ setShowCustomLabel }) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();

  const { sessionDetail } = useSessionTimeLine();
  
  
  const { urlReducer: urlQuery } =
  useSelector((state) => state);
  const { megaFilterCustomLabels: customLabels } = useCustomLabels();
  const {addSessionLabel, markSessionLabel} = useCustomLabelApi();
  const { parentType, sessionid, secondarysessionid, appId } = urlQuery;
  const isAiSession = parentType === 'aiSessionsList';
  const activeSessionId = isAiSession ? secondarysessionid : sessionid;
  const getDetailCacheKey = (id) => isAiSession ? getAIDetailsKey(id) : id;
  const sessionLabel = useMemo(
    () => sessionDetail?.customLabel,
    [sessionDetail]
  );
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let sessionsListOnDetailPayload = ''
  try {
    sessionsListOnDetailPayload = JSON.parse(localStorage.getItem(sessionBodyKey))
  } catch (err) {
    // silent fail
  }
  const sessionQueryKey = useMemo(() => [sessionKey, sessionsListOnDetailPayload], [sessionsListOnDetailPayload] )

  const customLabelsArray = useMemo(
    () => customLabels?.map((item) => item.name),
    [customLabels]
  );

  const [labelsOnSession, setLabelsOnSession] = useState([]);

  const closeLabel = () => {
    setShowCustomLabel(false);
  };

  const removeSessionLabel = (data, labelType) => {
    const markLabelName = data.customLabelName;
    const sessionUserIds = [sessionDetail?.userProperty?.uxcamuserid];
    let sessionUploadDate = [sessionDetail?.time?.sessionUploadedDateTime];

    if (!sessionDetail?.time?.sessionUploadedDateTime) {
      const allSessionCaches = queryClient.getQueriesData(['sessionItems']);
      const sessionFromAllCaches = allSessionCaches
        .map(([, cachedData]) => cachedData?.data?.data?.body)
        .filter(Boolean)
        .flat()
        .find((s) => s?.sessionid === activeSessionId);

      if (sessionFromAllCaches?.sessionUploadedDateTime) {
        sessionUploadDate = [sessionFromAllCaches.sessionUploadedDateTime];
      }
    }

    if (!sessionUploadDate[0] || !activeSessionId || !appId) {
      return;
    }

    const payload = {
      appid: appId,
      ...data,
      uxcamuserIds: sessionUserIds,
      sessionIds: [activeSessionId],
      uploadedOn: sessionUploadDate,
      labelType: labelType || 'session',
    };

    markSessionLabel(payload);

    [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) && queryClient.setQueryData(sessionQueryKey, (old) => {
      const bodyCopy = [...(old?.data?.data?.body ?? [])];
      let sessionObj = bodyCopy.find((el) => el.sessionid === activeSessionId);
      const value = data.isTagged;

      if (sessionObj && sessionObj?.customLabel?.includes(markLabelName) && !value) {
        const customLabelCopy = [...sessionObj.customLabel];
        customLabelCopy.splice(customLabelCopy.indexOf(markLabelName), 1);
        sessionObj = {
          ...sessionObj,
          customLabel: customLabelCopy,
        };
      } else if (value && sessionObj?.sessionid) {
        sessionObj = {
          ...sessionObj,
          customLabel: [...sessionObj?.customLabel ?? [], markLabelName],
        };
      }
      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: bodyCopy.map((el) => {
              if (el.sessionid === sessionObj?.sessionid) {
                return {
                  ...el,
                  customLabel:  uniq(sessionObj?.customLabel),
                };
              }
              return el;
            }),
          },
        },
      }
    });
  }

  const handleRemoveLabel = (data, labelType) => {
    const markLabelName = data.customLabelName;
    const marlLabelValue = data.isTagged;

    removeSessionLabel(data, labelType);

    const eventProperty = {
      'label name': markLabelName,
      'session ids' : [activeSessionId],
      'label_type': labelType || 'session',
    }
    
    dispatch(trackPageViews(null, {
      eventName: marlLabelValue ?  'add_label' : 'remove_label',
      track_type: 'event',
      eventProperty,
    }))

    let obj;
    const detailCacheKey = getDetailCacheKey(activeSessionId);
    const prevData = queryClient.getQueryData(detailCacheKey);
    if (prevData) {
      const customLabel = prevData?.customLabel || [];
      if (customLabel?.indexOf(markLabelName) > -1) {
        obj = customLabel.filter((item) => item !== markLabelName);
      } else {
        obj = [...customLabel, markLabelName];
      }
      queryClient.setQueryData(detailCacheKey, (previousData) => ({
        ...previousData,
        customLabel: obj,
      }));
    }
  };

  const handleLabelAddOnSession = (dataBody) => {
    const sessionIds = dataBody?.sessionIds || [];
    const sessionUserIds = [sessionDetail?.userProperty?.uxcamuserid];
    let sessionUploadDate = [sessionDetail?.time?.sessionUploadedDateTime];

    if (!sessionDetail?.time?.sessionUploadedDateTime) {
      const allSessionCaches = queryClient.getQueriesData(['sessionItems']);
      const sessionFromAllCaches = allSessionCaches
        .map(([, cachedData]) => cachedData?.data?.data?.body)
        .filter(Boolean)
        .flat()
        .find((s) => s?.sessionid === activeSessionId);

      if (sessionFromAllCaches?.sessionUploadedDateTime) {
        sessionUploadDate = [sessionFromAllCaches.sessionUploadedDateTime];
      }
    }

    if (!sessionUploadDate[0] || !sessionIds.length || !appId) {
      return;
    }

    const dataReloaded = {
      ...dataBody,
      appid: appId,
      uxcamuserIds: sessionUserIds,
      uploadedOn: sessionUploadDate,
      labelType: parentType === 'usersList' ? 'user' : 'session',
    };
    addSessionLabel(dataReloaded);
    dispatch(
      trackPageViews(null, {
        eventName: 'add_label',
        track_type: 'event',
        eventProperty: {
          'label name': dataReloaded?.customLabelName,
          'session ids': sessionIds,
          'label_type': parentType === 'usersList' ? 'user' : 'session',
        },
      })
    );
    
    [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) && queryClient.setQueryData(sessionQueryKey, (old) => {
        const newBody = old.data.data.body.map((el) => {
          if (sessionIds.length && sessionIds.includes(el.sessionid)) {
            const labelsData = el.customLabel ? [...el.customLabel] : [];
            return {
              ...el,
              customLabel: [...labelsData, dataBody.customLabelName],
            };
          }
          return el;
        });
        return {
          ...old,
          data: {
            ...old.data,
            data: {
              ...old.data.data,
              body: newBody,
            },
          },
        };
      });

    sessionIds.forEach((sid) => {
      const detailCacheKey = getDetailCacheKey(sid);
      const prevData = queryClient.getQueryData(detailCacheKey);
      if (prevData) {
        const customLabel = prevData?.customLabel || [];
        const newLabel = [...customLabel, dataBody.customLabelName];
        queryClient.setQueryData(detailCacheKey, (previousData) => ({
          ...previousData,
          customLabel: newLabel,
        }));
      }
    });
  };

  const handleSubmit = async (labelName, labelData) => {
    const obj = { name: labelName, icon: 'tag', sessioncount: 1 };
    const value = { customLabelName: labelName, labelIcon: 'tag' };

    if (labelName.length && !contains(labelData, labelName)) {
      customLabels.push(obj);
      customLabels.sort((a, b) =>
        a.name.localeCompare(b.name)
      );

      if (EnabledSessionLabelParentTypes.includes(parentType)) {
        const combinedData = {
          ...value,
          sessionIds: [activeSessionId],
        };
        handleLabelAddOnSession(combinedData);
      }
    }
  };

  useEffect(() => {
    if (EnabledSessionLabelParentTypes.includes(parentType)) {
      const result = sessionLabel?.filter(
        (label) => customLabelsArray.indexOf(label) >= 0
      );
      setLabelsOnSession(result);
    } else {
      setLabelsOnSession(sessionLabel);
    }
  }, [sessionLabel, parentType, customLabelsArray, customLabels?.length]);

  return (
    <CommonCustomLabel
      addedLabels={labelsOnSession}
      handleRemoveLabel={handleRemoveLabel}
      addLabel={handleSubmit}
      handleMarkLabel={handleRemoveLabel}
      handleCloseLabel={closeLabel}
      labelCountBy="count"
    />
  );
};

export default memo(SessionCustomLabels);
