import React, { useEffect, useRef, useState, useCallback, useMemo } from 'react';
import { Tag, Input, Popover, Tooltip, message } from 'antd';
import { useSelector } from 'react-redux';
import Cookies from 'universal-cookie';
import $ from 'jquery';
import _ from 'underscore';
import { CloseOutlined } from '@ant-design/icons';

import { LabelAddIcon, LabelUpIcon } from 'components/svg_files';
// import TooltipTruncatedText from 'Utils/helpers/TooltipTruncatedText';

import styled from 'styled-components';

import useCustomLabels from 'hooks/useCustomLabels';
import find from 'lodash/find';
import ManageCustomLabel from './ManageCustomLabel';
import LabelsDropdownOverlay from './LabelsDropdownOverlay';


const messageText =
'You are not allowed to perform this action from the guest login.';

const RightWrapper = styled.div`
  position: relative;
  display: flex;
  .btn-up-icon{
    display: inline-block;
    cursor: pointer;
    text-align: center;
    margin: 0px;
    margin-left: 10px;
    height: 24px;
    line-height: 24px;
    width: 24px;
  }
`

const CreateLabelWrapper = styled.button`
  margin: 0px;
  padding: 2px 8px;
  height: 28px;
  border-radius: 4px;
  border: none;
  outline: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: transparent;
  font-size: 12px;
  cursor: pointer;

  &:hover {
    background-color: #EFF5FF;
  }

  .label-press {
    font-size: 10px;
    color: #A2A5AE;
  }

  .label-name {
    display: flex;
    align-items: center;
    gap: 8px;

    svg {
      width: 14px;
      height: 14px;
    }

    span {
      display: flex;
      strong {
        flex: 1;
        max-width: 40px;
  
        overflow-x: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
  
      }
    }
  }
`

const CustomLabel = ({
  addedLabels,
  handleRemoveLabel,
  addLabel,
  handleMarkLabel,
  handleCloseLabel,
  labelCountBy
}) => {
  const cookies = new Cookies();
  const {
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const {
    megaFilterSessionLabels,
    labelSearch, 
    setLabelSearch,
    megaFilteredSessionLabels,
    filteredUserLabels,
    userLabels,
    compareLabels,
    resetSearch,
    getLabelTypeFromValue,
    checkExistingLabel,
  } = useCustomLabels();
  const parentType = urlQuery?.parentType;
  const isUserList = parentType === 'usersList';
  const [selectedCustomLabelTab, setSelectedCustomLabelTab] = useState(isUserList ? 'user' : 'session');
  const customLabels = useMemo(() => isUserList ? userLabels : megaFilterSessionLabels, [isUserList, userLabels, megaFilterSessionLabels])

  const loginInFromGuest = cookies.get('loggedInType');
  const inputRef = useRef(null);
  const elementRef = useRef();

  const [displayInput, setDisplayInput] = useState(false);
  const [labelListVisible, setLabelListVisible] = useState(false);
  const [totalLabel, setTotalLabels] = useState([]);
  const [labelData, setLabelData] = useState([]);
  const [labelName, setLabelName] = useState('');
  const [boxWidth, setBoxWidth] = useState(`${100}px`);


  const labelTabs = useMemo(() => isUserList ? [
      {
          key: 'user',
          name: 'User label',
          options: 
          filteredUserLabels.sort((a, b) => compareLabels(addedLabels, a, b)), // includes filtered labels
          showSearch: false,
      }
    ] : [
      {
          key: 'session',
          name: 'Session label',
          options: 
          megaFilteredSessionLabels.sort((a, b) => compareLabels(addedLabels, a, b)), // includes filtered labels
          showSearch: false,
      }
    ], [isUserList, megaFilteredSessionLabels, filteredUserLabels, addedLabels])
  
  const handleShowInput = () => setDisplayInput(true);
  const handleLabelSorting = (labels) =>
    labels
      .sort(
        (a, b) => a.name.length - b.name.length && a.name.localeCompare(b.name)
      )
      .sort((a, b) => (a[labelCountBy] <= b[labelCountBy] ? 1 : -1));

  const handleListVisibleChange = (visible) => setLabelListVisible(visible);

  const closeLabel = () => {
    handleCloseLabel()
    setDisplayInput(false);
  };

  const handleCustomLabelAdd = () =>{
    if(labelName?.length > 2 && labelName?.length <= 50){
      if (!checkExistingLabel(labelName)) {
        addLabel(labelName.trim(), labelData)
        setLabelListVisible(false)
      } else message.error('Label already exists.')
    } else message.error(`Label name must be ${labelName?.length <= 2 ? 'more than 2' : 'less than 50' } characters.`)
  }

  const handleChange = async (e) => {
    const { value } = e.target;
    setLabelName(value);
    setBoxWidth(`${value?.length >= 10 ? (value.length + 1) * 7 : 85}px`);
    const filterName = customLabels.filter(
      (label) => label?.name?.toLowerCase().indexOf(value.toLowerCase()) >= 0
    );
    setLabelSearch({
      sessionLabels: value,
      userLabels: value,
    })
    await setTotalLabels(handleLabelSorting(filterName));
  };

  const handleLabelRemove = (value, labelType) =>{
    if (loginInFromGuest !== 'guest') {
      const data = {
        customLabelName: value,
      };
      data['isTagged'] = false;
      handleRemoveLabel(data, labelType)
     
    } else {
       message.info(messageText);
    }
  
  }

  const handleCustomLabelClick = (key, label) => {
    const selectedLabel = find(label.options, { name: key });
    if (loginInFromGuest !== 'guest') {
      const data = {
        customLabelName: selectedLabel?.name,
      };
      data['isTagged'] = true;
      setLabelName('');
      setTotalLabels(handleLabelSorting(customLabels));
      setLabelListVisible(false);
      if (addedLabels?.includes(key)) {
        handleLabelRemove(key, selectedLabel.labelType);
      } else {
        handleMarkLabel(data, selectedLabel.labelType)
      }
    } else {
        message.info(messageText);
    }
  }

  const separateLabelName = (labels) => {
    const labelList = [];
    labels.length ? labels.map((label) => labelList.push(label.name)) : '';
    setLabelData(labelList);
  };

  const handleCustomLabelTabChange = (key) => {
    setSelectedCustomLabelTab(key);
    inputRef.current.focus();
  }

  const handleLabelSearch = useCallback((e) => {
    setLabelSearch({
      sessionLabels: labelName,
      userLabels: labelName,
    })
  }, [labelSearch, selectedCustomLabelTab, setLabelSearch])

  useEffect(() => {
    $('.sd-scrollbar').animate({ scrollLeft: '+=357px' }, 'slow');
  }, [addedLabels]);

  useEffect(() => {
    separateLabelName(customLabels);
    setTotalLabels(handleLabelSorting(customLabels));
  }, [customLabels, customLabels?.length, labelListVisible === true]);

  useEffect(() => {
    if (inputRef?.current) {
      setLabelListVisible(true);
      inputRef?.current?.focus();
    }
  }, [displayInput]);

  useEffect(() => {
    if (!labelListVisible) {
      setDisplayInput(labelListVisible);
      setLabelName('');
      setBoxWidth('100px');
      setTotalLabels(handleLabelSorting(customLabels));
      resetSearch();
    }
    if(isUserList) {
      setSelectedCustomLabelTab('user');
    }
  }, [labelListVisible]);

  const getAddLabelShowKey = useMemo(() => isUserList ? 'user' : 'session', [isUserList])

  const displayEmptyLabelMessage = useMemo(() => {
    if (selectedCustomLabelTab === 'session' && megaFilterSessionLabels?.length <= 0)
      return `You haven't created any label.`
    if (selectedCustomLabelTab === 'user' && userLabels?.length <= 0)
      return `You haven't created any label.`
    return null
  }, [megaFilterSessionLabels?.length, selectedCustomLabelTab, userLabels?.length])

  const renderLabelAdd = labelName?.length && !checkExistingLabel(labelName) && selectedCustomLabelTab === getAddLabelShowKey ?
            <CreateLabelWrapper
              aria-hidden="true"
              key="submit"
              onClick={() => handleCustomLabelAdd()}
              className={`create-label-btn ${
                totalLabel.filter(
                  (label) => !_.contains(addedLabels, label.name)
                )?.length === 0
                  ? 'active-label'
                  : ''
              }`}
            >
              <div className="label-name">
                <LabelAddIcon /> 
                  <span>
                    Create label &quot;<strong>{`${labelName}`}</strong>&quot;
                  </span>
              </div>
              <div className="label-press">Press enter</div>
            </CreateLabelWrapper> : null
            
  return (
    <div className="session-detail-custom-label">
    <div
      className={`left-wrapper ${
        customLabels?.length === 0 ? 'manage-hide' : ''
      }`}
      ref={elementRef}
    >
      <div className="left-shadow" />
      <div className="sd-scrollbar">
        {addedLabels?.length > 0 &&
          addedLabels
            .sort((a, b) => a.localeCompare(b))
            .map((label) =>
              !urlQuery?.shareSessionKey ? (
                <Tag key={label}>
                  <span key={label} className="tag-name">
                    {label}
                    <CloseOutlined
                      onClick={() => handleLabelRemove(label, getLabelTypeFromValue(label))}
                    />
                  </span>
                </Tag>
              ) : (
                <Tag key={label}>
                  <span className="tag-name" key={label}>
                    {label}
                  </span>
                </Tag>
              )
            )}
        {displayInput &&
        !urlQuery?.shareSessionKey &&
        loginInFromGuest !== 'guest' ? (
          <Popover
            content = {
              <LabelsDropdownOverlay 
                tabs={labelTabs}
                selectedKeys={addedLabels}
                handleItemClicked={handleCustomLabelClick}
                handleTabChange={handleCustomLabelTabChange}
                emptyLabelMessage={
                  displayEmptyLabelMessage
                }
                hideFooter
                footer={renderLabelAdd}
                searchInput={{
                  placeholder: 'Search label',
                  value: labelName,
                  onChange: handleLabelSearch,
                }}
                showLabelCount
                />
            }
            trigger="click"
            placement="bottomLeft"
            visible={labelListVisible}
            onVisibleChange={handleListVisibleChange}
            overlayClassName={`label-add-dropdown ${
              addedLabels?.length > 1 ? '' : 'label-empty'
            }`}
            overlayStyle={{padding: 0}}
            getPopupContainer={(triggerNode) =>
              triggerNode && triggerNode?.parentNode
            }
          >
            <Input
              ref={inputRef}
              value={labelName}
              style={{ width: boxWidth }}
              onPressEnter={handleCustomLabelAdd}
              className="custom-label-input"
              onChange={handleChange}
              placeholder="type to add..."
            />
          </Popover>
        ) : (
          <div className="tag-item">
            {!urlQuery?.shareSessionKey && (
              <Tag onClick={() => handleShowInput()}>
                <Tooltip
                  className="add-label-tooltip"
                  title={`Click to add ${
                    isUserList ? 'user' : 'session'
                  } label`}
                  placement="bottom"
                >
                  <span className="add-label">{`+ Add ${
                    isUserList ? 'user' : 'session'
                  } label`}</span>
                </Tooltip>
              </Tag>
            )}
          </div>
        )}
      </div>
    </div>
    <RightWrapper>
      {!urlQuery?.shareSessionKey &&
        loginInFromGuest !== 'guest' &&
        customLabels?.length !== 0 && <ManageCustomLabel />}
      <div
        className="btn-up-icon"
        aria-hidden="true"
        onClick={() => closeLabel()}
      >
        <LabelUpIcon />
      </div>
    </RightWrapper>
  </div>
  );
};

export default CustomLabel;
