/* eslint-disable react/no-array-index-key */
import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Input, Button, Popconfirm, Popover, Tooltip } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import { DeleteOutlined, SettingOutlined, SearchOutlined } from '@ant-design/icons';
import { useQueryClient } from 'react-query';

import {
  addSegmentV2,
  applyIssuesCustomFilter,
  applySessionCustomFilter,
  applyUserCustomFilter,
} from 'redux/actions/filter';

import { FilterIconSVG } from 'components/svg_files/index';
import TooltipTruncatedText from 'Utils/helpers/TooltipTruncatedText';
import { callSessionStatisticsAPI } from 'redux/actions/megaFilter';
import { gotUserDetail } from 'redux/actions/userList/actionObjects'

import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';
import useIssueListAPI from 'components/features/issues/hooks/useIssueListAPIs';
import { ManageLabelButton, PopoverContent } from './styles';

const CustomLabelManage = () => {
  const dispatch = useDispatch();
  const inputRef = useRef(null);
  const {
    urlReducer: urlQuery,
    sessionDetailReducer: sessionDetail,
    currentAppReducer: { _id: appId },
    userDetailReducer,
  } = useSelector((state) => state);
  const queryClient = useQueryClient();
  const { data: userDetails } = userDetailReducer;
  const {megaFilterSessionLabels, userLabels} = useCustomLabels();
  let issueListQueryKey = '';
  let screenListQueryKey = '';
  
  try {
    issueListQueryKey = JSON.parse(localStorage.getItem('issuesListReqBody'));
    screenListQueryKey = JSON.parse(localStorage.getItem('screensListReqBody'));
  } catch (err) {
    // silent fail
  }
  
  const issueDetailResponse = queryClient.getQueryData(issueListQueryKey);
  const screenDetailResponse = queryClient.getQueryData(['heatmaps-screen-visits', screenListQueryKey]);

  const totalDeatailList = useMemo(() => {
    const issueList = issueDetailResponse?.data?.data?.body || [];
    const screenList = screenDetailResponse?.body || [];
    return [...issueList, ...screenList];
  }
  , [issueDetailResponse, screenDetailResponse])
  
  const sessionIds = useMemo(() => totalDeatailList?.map(
          (item) => item.sessionid
        ), [totalDeatailList])

  const { deleteLabel } = useCustomLabelApi();

  const { parentType, sessionid, uxcamuserid } = urlQuery;
  const isUserList = parentType === 'usersList';
  const customLabels = useMemo(
    () => (isUserList ? userLabels : megaFilterSessionLabels),
    [isUserList, userLabels, megaFilterSessionLabels]
  );
  const { session, user, issue } = useSelector((state) => state.appFilter);

  const sessionSegment = session?.segment || [];
  const userSegment = user?.segment || [];
  const issueSegment = issue?.segment || [];
  const [searchValue, setSearchValue] = useState();
  const [visible, setVisible] = useState();
  const [orderedCustomLabels, setOrderedCustomLabels] = useState();

  const handleManageVisibleChange = (value) => {
    setVisible(value);
    setSearchValue('');
    if (!value) setOrderedCustomLabels(customLabels);
  };
  const sessionLabel = sessionDetail?.data?.customLabel || [];
  const labelOnUserDetail = userDetails?.customLabel || [];
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let queryKey = ''
  try {
    queryKey =
      parentType === 'usersList'
        ? ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]
        : [ sessionKey,JSON.parse(localStorage.getItem(sessionBodyKey)),];
  } catch (err) {
    // silent fail
  }
  // const sessionQueryKey = `${sessionid}`;

  const updateUserDetail = (labelName) => {
    const newUserDetail = { ...userDetails };
    newUserDetail.customLabel = labelOnUserDetail?.filter(
      (label) => label !== labelName
    );
    dispatch(gotUserDetail(newUserDetail));
  };

  const commonDeleteLabel = (data) => {
    const dataV2 = {
      ...data,
      appid: appId,
    };

    deleteLabel(dataV2)

    const labelName = data?.customLabelName;
    [ 'sessionsList', 'aiSessionsList', 'usersList' ].includes( parentType )  &&
    queryClient.setQueryData(queryKey, (old) => {
      const newBody = old.data.data.body.map((el) => ({
        ...el,
        customLabel: el.customLabel.filter((label) => label !== labelName),
      }));

      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });

    if (sessionIds?.length) {
      let obj;
      const uniqSessionIds = [...new Set(sessionIds)];
      uniqSessionIds.forEach((id) => {
        const prevData = queryClient.getQueryData(id);
        if (prevData) {
          const customLabel = prevData?.customLabel || [];
          if (customLabel?.length) {
            obj = customLabel.filter((item) => item !== labelName);
          }
          queryClient.setQueryData(id, (previousData) => ({
            ...previousData,
            customLabel: obj,
          }));
        }
      });
    }
  };
  const handleLabelDelete = (name) => {
    const combinedData = {
      customLabelName: name,
      labelType: parentType === 'usersList' ? 'user' : 'session',
    };
    commonDeleteLabel(combinedData);

    if (sessionid) {
      const sortedCustomField = sessionLabel
        .filter((label) => label !== name)
        .sort();
      if (sessionDetail)
        sessionDetail.data.customLabel = [...sortedCustomField];
    }
    if (uxcamuserid && isUserList) {
      updateUserDetail(name);
    }

    setVisible(false);
  };

  const handleCustomLabelSearch = (e) => {
    setSearchValue(e.target.value);
    const searchResult =
      customLabels &&
      customLabels.filter(
        (obj) =>
          obj.name.toLowerCase().indexOf(e.target.value.toLowerCase()) >= 0
      );
    setOrderedCustomLabels(searchResult);
  };
  const applyQuickFilter = async (value) => {
    const segment = (table) => ({
      attribute: table === 'appuser' ? 'user_custom_label' : 'custom_label',
      operator: 'has_any',
      value: [value],
      table,
    });
    let segmentValue = [];
    
    segmentValue = isUserList ? userSegment : sessionSegment;
    if (parentType === 'issues') {
      segmentValue = issueSegment;
    }
    segmentValue.push(!isUserList ? segment('session') : segment('appuser'));
    if (!isUserList) {
      if (parentType === 'issues') {
        await dispatch(addSegmentV2(segmentValue, 'issue-filter'));
        dispatch(applyIssuesCustomFilter(1, 'issue'));
        return;
      }
      await dispatch(addSegmentV2(segmentValue, 'session-filter'));
      dispatch(callSessionStatisticsAPI());
      dispatch(applySessionCustomFilter(1, 'session'));
    } else {
      await dispatch(addSegmentV2(segmentValue, 'user-filter'));
      dispatch(applyUserCustomFilter(1, 'user', true));
    }
    setVisible(false);
    setSearchValue('');
    setOrderedCustomLabels(customLabels);
  };

  useEffect(() => {
    setOrderedCustomLabels(customLabels);
  }, [customLabels?.length]);

  useEffect(() => {
    const timer =
      visible &&
      setTimeout(() => {
        inputRef?.current?.focus();
      }, 500);

    return () => {
      clearInterval(timer);
    };
  }, [inputRef?.current, visible]);

  const manageMenu = (
    <PopoverContent>
      <Input
        placeholder="Search labels"
        value={searchValue}
        ref={inputRef}
        className="label-search-box"
        onChange={handleCustomLabelSearch}
        prefix={<SearchOutlined />}
      />
      <div className="manage-dropdown-height">
        {orderedCustomLabels instanceof Array &&
          orderedCustomLabels?.map((label, index) => (
            <div key={index + label.name} className="label-item">
              <div className="label-name">
                <TooltipTruncatedText>{label.name}</TooltipTruncatedText>
              </div>
              <div className="label-action">
                <Tooltip
                  placement="topRight"
                  title={`Show ${isUserList ? 'users' : 'sessions'} with '${
                    label.name
                  }' label only`}
                >
                  {(['sessionsList', 'aiSessionsList', 'usersList', 'issues'].includes(parentType)) && (
                    <Button
                      icon={<FilterIconSVG />}
                      onClick={() => applyQuickFilter(label.name)}
                      className="btn-filter-icon"
                    />
                  )}
                </Tooltip>
                <Popconfirm
                  overlayClassName="delete-pop-confirm"
                  getPopupContainer={() => document.body}
                  onConfirm={() => handleLabelDelete(label.name)}
                  title={
                    <div>{`Delete this label permanently from all ${
                      isUserList ? 'users' : 'sessions'
                    }?`}</div>
                  }
                  okText="Delete"
                  icon={null}
                  cancelText="Cancel"
                >
                  <Button icon={<DeleteOutlined />} />
                </Popconfirm>
              </div>
            </div>
          ))}
      </div>
    </PopoverContent>
  );

  return (
    <Popover
      content={manageMenu}
      trigger="click"
      placement="bottom"
      visible={visible}
      getPopupContainer={trigger => trigger.parentNode}
      overlayClassName='label-manage-dropdown'
      onVisibleChange={handleManageVisibleChange}
    >
      <ManageLabelButton>
        <SettingOutlined /> Manage label
      </ManageLabelButton>
    </Popover>
  );
};

export default CustomLabelManage;
