/* eslint-disable no-unused-expressions */
import Link from 'next/link';
import React, { useMemo, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import _ from 'underscore';
import { InfoCircleOutlined } from '@ant-design/icons';
import { Tooltip } from 'antd';

import {
  addSegmentV2,
  applySessionCustomFilter,
  applyUserCustomFilter,
} from 'redux/actions/filter';
import { addSessionId } from 'redux/actions/common';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { trackPageViews } from 'redux/actions/trackingReport';
import { callSessionStatisticsAPI, callEventsListAndGraphApi } from 'redux/actions/megaFilter';
import { removeValuesFromFilters } from 'Utils/helpers/commonUtils';

const LinkHeaderAttribute = ({
  children,
  segment,
  _attribute,
  __value: value = {},
  _operator = 'in',
  _isNotArrayFormat: notArrayFormat,
  tooltipTitle_value: tooltipTitleValue,
  isClickableLink,
  table
}) => {
  const dispatch = useDispatch();
  const { urlReducer: urlQuery } = useSelector((state) => state);
  let object;
  const equalTo = '=';
  let clonedSegment = _.clone(segment);
  const [setUrl, setAsUrl] = useState('');
  const [newSegment, setNewSegment] = useState([]);
  const setUrlSegment = async (attribute, valueArg, operator) => {
    const checkedValue = notArrayFormat ? valueArg : [valueArg];
    const ruleByAttribute = {
      attribute,
      operator: operator || 'in',
      value: checkedValue,
      table
    };
    let asUrl;
    asUrl = `/app/${urlQuery.appId}/sessions/list/1/${urlQuery.sessionid}?`;
    if (urlQuery.parentType === 'usersList') {
      asUrl = `/app/${urlQuery.appId}/users/list/1/${urlQuery.uxcamuserid}?`;
    }
    if (urlQuery.parentType === 'issues') {
      asUrl = `/app/${urlQuery.appId}/issues/${urlQuery.issueType}/${urlQuery.issuepage}/${urlQuery.issueid}/${urlQuery.issuedetailpage}/session/${urlQuery.sessionid}/${urlQuery.starttime}?`;
    }
    if (urlQuery.parentType === 'eventsList') {
      asUrl = `/app/${urlQuery.appId}/events/list/${urlQuery.eventpage}/${urlQuery.sessionid}/${urlQuery.eventid}/${urlQuery.starttime}?`;
    }
    if (urlQuery.parentType === 'nocodeEventsList') {
      asUrl = `/app/${urlQuery.appId}/smart-events/list/${urlQuery.eventpage}/${urlQuery.sessionid}/${urlQuery.eventid}/${urlQuery.starttime}?`;
    }
    if (clonedSegment.length) {
      const pluckedArray = _.pluck(clonedSegment, 'attribute');
      const isAttributeAvailable = pluckedArray.includes(attribute);
      const attributeIndex =
        isAttributeAvailable &&
        _.findLastIndex(clonedSegment, {
          attribute,
        });
      if (
        isAttributeAvailable &&
        attributeIndex >= 0 &&
        _operator === clonedSegment[attributeIndex].operator
      ) {
        if (attribute === 'platform') {
          clonedSegment[attributeIndex].operator = operator;
        } else if (
          !_.isEmpty(clonedSegment[attributeIndex].value) &&
          !clonedSegment[attributeIndex].value.includes(value)
        ) {
          if (notArrayFormat) clonedSegment[attributeIndex].value = value;
          else
            clonedSegment[attributeIndex].value = [
              ...clonedSegment[attributeIndex].value,
              ...value,
            ];
          if (attribute === 'session_uploadedon') {
            clonedSegment[attributeIndex].operator = operator;
          }
        }
      } else {
        clonedSegment.push(ruleByAttribute);
      }
      asUrl = urlSegmentEncoder(asUrl, clonedSegment);
    } else {
      clonedSegment = [ruleByAttribute];
      object = JSON.stringify({ o: operator || 'in', v: value, tb: table });
      asUrl = asUrl.concat(attribute, equalTo, object);
      asUrl = encodeURI(asUrl);
    }
    setNewSegment(clonedSegment);
    setAsUrl(asUrl);
  };

  const applyFilterinSessionStatsWithTable = () => {
    dispatch(trackPageViews(null, {
      eventName: 'create_filter',
      track_type: 'event',
      eventProperty: removeValuesFromFilters(newSegment),
      pageName: urlQuery.parentType,
    }))
    // dispatch(applyCustomFilter(1, 'session', 'sessionStatistics'));
    dispatch(callSessionStatisticsAPI())
    dispatch(applySessionCustomFilter(1, 'session'));
  };

  const getQuery = useMemo(() => {
    if ( [ 'sessionsList' ].includes( urlQuery.parentType )) {
      return {
        appId: urlQuery.appId,
        parentType: urlQuery.parentType,
        sessionid: urlQuery.sessionid,
        sessionpage: 1,
      };
    }  
    if (urlQuery.parentType === 'issues') {
      return {
        appId: urlQuery.appId,
        parentType: urlQuery.parentType,
        issueType: urlQuery.issueType,
        issuepage: urlQuery.issuepage,
        issueid: urlQuery.issueid,
        issuedetailpage: urlQuery.issuedetailpage,
        sessionid: urlQuery.sessionid,
        starttime: urlQuery.starttime,
      };
    }
    if ([ 'eventsList', 'nocodeEventsList' ].includes(urlQuery.parentType)) {
      return {
        appId: urlQuery.appId,
        parentType: urlQuery.parentType,
        sessionid: urlQuery.sessionid,
        eventid: urlQuery.eventid,
        starttime: urlQuery.starttime,
        eventpage: urlQuery.eventpage,
      };
    }
    return {
      appId: urlQuery.appId,
      parentType: urlQuery.parentType,
      sessionid: urlQuery.sessionid,
      sessionpage: 1,
    };
  }, [urlQuery]); 

  return  [ 'sessionsList' ].includes( urlQuery.parentType ) || isClickableLink ? (
    <Link
      href={{
        pathname: '/integration',
        query: getQuery,
      }}
      as={setUrl}
      passHref
      legacyBehavior
    >
      <a
        onFocus={() => setUrlSegment(_attribute, value, _operator)}
        onMouseOver={() => setUrlSegment(_attribute, value, _operator)}
        onMouseLeave={() => setNewSegment({})}
        href="#!"
      >
        <span
          aria-hidden="true"
          onClick={() => {
            dispatch(addSessionId([]));
            let filterType = 'user-filter';
            if ([ 'sessionsList', 'aiSessionsList' ].includes( urlQuery.parentType )) {
              filterType = 'session-filter';
            } else if (['eventsList', 'nocodeEventsList'].includes(urlQuery.parentType)) {
              filterType = 'event-filter';
            }
            dispatch(addSegmentV2(newSegment, filterType));
            if ([ 'sessionsList', 'aiSessionsList' ].includes( urlQuery.parentType )) {
              applyFilterinSessionStatsWithTable();
            } else if (['eventsList', 'nocodeEventsList'].includes(urlQuery.parentType)) {
              dispatch(callEventsListAndGraphApi());
            } else {
              dispatch(applyUserCustomFilter(1, 'user', true));
            }
          }}
        >
          <ToolTipContext
            children_value={children}
            tooltipTitle_value={tooltipTitleValue}
            isSessionsList
          />
        </span>
      </a>
    </Link>
  ) : (
    <ToolTipContext
      children_value={children}
      tooltipTitle_value={tooltipTitleValue}
    />
  );
};
const ToolTipContext = ({
  children_value: childrenValue,
  tooltipTitle_value: tooltipTitleValue,
  isSessionsList,
}) => (
  <Tooltip
    title={
      tooltipTitleValue && (
        <div style={{ textAlign: 'left' }}>
          {tooltipTitleValue}
          {isSessionsList && (
            <div className="click-info">
              <InfoCircleOutlined /> Click to filter
            </div>
          )}
        </div>
      )
    }
  >
    {childrenValue}
    <style>{`
      .click-info{
          border-top: 1px solid #737373;
          padding-top: 7px;
          margin-top: 7px;
      }
    `}</style>
  </Tooltip>
);

export default LinkHeaderAttribute;
