import React, { useMemo } from 'react';
import { Tooltip, Badge } from 'antd';
import Link from 'next/link';
import { getUtcDate } from 'Utils/DateConversion/dateConversionUtils';
import LinkHeaderAttribute from 'components/common/LinkHeaderAttribute';
import LocationIcon from 'public/static/session-replay/location.svg';
import CalendarIcon from 'public/static/session-replay/calendar.svg';
import LabelsIcon from 'public/static/session-replay/label.svg';
import { trackPageViews } from 'redux/actions/trackingReport';
import { setFilterPageTable } from 'redux/actions/megaFilter';
import { useDispatch } from 'react-redux';
import { getTimeDuration, getUserNameConfig } from 'components/features/aiSessions/components/utils';
import { HeaderItem, LabelContainer } from './styles';
import IssueInfo from './IssueInfo';
import {
  UserNameComponentProps,
  LocationHeaderComponentProps,
  DateHeaderComponentProps,
  LabelsComponentProps,
  IssueInfoComponentProps,
  UserNameComponentV2Props
} from './types';

export const UserNameComponent: React.FC<UserNameComponentProps> = ({ 
  sessionDetails, 
  appId, 
  urlQuery, 
  parentType, 
}) => {
  const dispatch = useDispatch();
    
  const getUserName = sessionDetails.isAlias ? (
    <Tooltip
      title={
        <span>
          {sessionDetails.name || sessionDetails.uxcamuserid}
          <br />
          (Randomly assigned alias based on country of IP)
        </span>
      }
    >
      <span className="text-ellipsis">
        {sessionDetails.name || sessionDetails.uxcamuserid} *
      </span>
    </Tooltip>
  ) : (
    <span className="text-ellipsis">
      {sessionDetails.name || sessionDetails.uxcamuserid}
    </span>
  );

  return useMemo(
    () =>
      urlQuery.shareSessionKey ? (
        getUserName
      ) : (
        <Link
          href={{
            pathname: '/integration',
            query: {
              appId,
              parentType: 'usersList',
              uxcamuserid: sessionDetails.uxcamuserid,
              sessionPage: 1,
              userpage: 1,
            },
          }}
          as={`/app/${appId}/users/list/1/${sessionDetails.uxcamuserid}`}
          passHref
          legacyBehavior
        >
          <a
            href="#!"
            onClick={() => {
              parentType === 'eventsList' && dispatch(setFilterPageTable('appuser'))
              dispatch(
                trackPageViews(null, {
                  eventName: 'click_gotouser',
                  track_type: 'event',
                  pageName: parentType,
                  eventProperty: {
                    userId: sessionDetails?.uxcamuserid,
                    sessionId: sessionDetails?.sessionid,
                  },
                })
              )}
            }
          >
            {getUserName}
          </a>
        </Link>
      ),
    [sessionDetails, appId]
  );
};
export const UserNameComponentV2: React.FC<UserNameComponentV2Props> = ({ 
  session,
  appId, 
  urlQuery, 
  parentType, 
}) => {
  const dispatch = useDispatch();
  const uxcamuserid = session?.userProperty?.uxcamuserid || '';
  const getUserName = useMemo(()=>{
  if(!session?.userProperty) return null;
  const username = getUserNameConfig( session?.userProperty)
    return (
      <Tooltip title={username.tooltip}>
        <span className="text-ellipsis" style={{ fontStyle: username.tooltip ? 'italic' : 'normal' }}>
          {username.content}
        </span>
      </Tooltip>
    );
  },[session?.userProperty])

  return useMemo(
    () =>
      urlQuery.shareSessionKey ? (
        getUserName
      ) : (
        <Link
          href={{
            pathname: '/integration',
            query: {
              appId,
              parentType: 'usersList',
              uxcamuserid,
              sessionPage: 1,
              userpage: 1,
            },
          }}
          as={`/app/${appId}/users/list/1/${uxcamuserid}`}
          passHref
          legacyBehavior
        >
          <a
            href="#!"
            onClick={() => {
              parentType === 'eventsList' && dispatch(setFilterPageTable('appuser'))
              dispatch(
                trackPageViews(null, {
                  eventName: 'wa_sessions_click_user',
                  track_type: 'event',
                  pageName: parentType,
                  eventProperty: {
                    userId: uxcamuserid,
                    sessionId: session?.sessionid,
                  },
                })
              )}
            }
          >
            {getUserName}
          </a>
        </Link>
      ),
    [urlQuery.shareSessionKey, getUserName, appId, uxcamuserid, parentType, dispatch, session?.sessionid]
  );
};

export const LocationHeaderComponent: React.FC<LocationHeaderComponentProps> = ({ 
  sessionDetails, 
  pageSegment,
  isClickableLink = true
}) => {
  return useMemo(() => {
    const city = sessionDetails?.city || 'Undetermined City';
    const country = sessionDetails?.country || 'N/A';

    const attribute = sessionDetails?.city === 'N/A' ? 'device_country' : 'device_city';
    const value =
      sessionDetails?.city === 'N/A'
        ? sessionDetails?.country
        : sessionDetails?.city;

    const locationTooltip = `Location is ${
      sessionDetails?.city === 'N/A' ? 'Undetermined city' : sessionDetails?.city
    }, ${sessionDetails?.country || 'N/A'}`;

    return (
      <HeaderItem>
        <LocationIcon />{' '}
        <LinkHeaderAttribute
          segment={pageSegment}
          _attribute={attribute}
          __value={value}
          tooltipTitle_value={locationTooltip}
          _operator="in"
          table='session'
          isClickableLink={isClickableLink}
          _isNotArrayFormat={false}
        >
          {city}, {country}
        </LinkHeaderAttribute>
      </HeaderItem>
    );
  }, [isClickableLink, pageSegment, sessionDetails?.city, sessionDetails?.country]);
};

export const DateHeaderComponent: React.FC<DateHeaderComponentProps> = ({
  sessionDetails,
  pageSegment,
  isClickableLink = true,
  isV2= false,
  parentType
}) => {
    return useMemo(() => {
    const dateTimeObj = sessionDetails?.deviceLocalDateTime;
    const dateTimeDashFormat = dateTimeObj && getUtcDate(dateTimeObj, 'yyyy-MM-dd');
    const dateTimeSlashFormat = dateTimeObj && getUtcDate(dateTimeObj, 'dd-MMMM-yyyy');
    let displayDateTimeSlashFormat = dateTimeObj && getUtcDate(dateTimeObj, 'MMM d, yyyy');
    const dateDayTime = dateTimeObj && getUtcDate(dateTimeObj, 'EEEE hh:mm a')
    
    let tooltip = `Device time: ${dateDayTime}, ${dateTimeSlashFormat}`;

    if(isV2){
        const dateWithUTC = sessionDetails?.deviceLocalDateTime && getTimeDuration(sessionDetails.deviceLocalDateTime, sessionDetails.userTimezone)
        displayDateTimeSlashFormat = dateWithUTC && dateWithUTC[0];
        const splitDateTime = dateDayTime?.split(' ') || []
        const day = splitDateTime[0] || ''
        const time = dateWithUTC && dateWithUTC[1]?.split(',')[1]?.trim() || '';
        const year = sessionDetails?.deviceLocalDateTime && new Date(sessionDetails.deviceLocalDateTime).getFullYear();
        const UTCstr = dateWithUTC && dateWithUTC[2] || '';
        const formattedDate = dateWithUTC && dateWithUTC[1] || '';
        tooltip = `Device time: ${day}, ${formattedDate?.split(',')[0]}, ${year} at ${time} ${UTCstr}`;
    }

    const attr = ['eventsList','nocodeEventsList'].includes(parentType) ? 'event_recordedon' : 'session_recordedon';
    return (
      <HeaderItem>
        <CalendarIcon />
        <LinkHeaderAttribute
          segment={pageSegment}
          _attribute={attr}
          __value={dateTimeDashFormat}
          _operator="on"
          _isNotArrayFormat
          tooltipTitle_value={tooltip}
          table='session'
          isClickableLink={isClickableLink}
        >
          {displayDateTimeSlashFormat}
        </LinkHeaderAttribute>
      </HeaderItem>
    );
  }, [sessionDetails.deviceLocalDateTime, sessionDetails.userTimezone, isV2, parentType, pageSegment, isClickableLink]);
};


export const LabelsComponent: React.FC<LabelsComponentProps> = ({ 
  labelSession, 
  showCustomLabel, 
  setShowCustomLabel 
}) => {
  return (
    <HeaderItem data-intercom-target="Session Label">
      <span
        aria-hidden="true"
        onClick={() => setShowCustomLabel(!showCustomLabel)}
        className="labels-nav"
      >
        <Tooltip
          overlayClassName="session-label-tooltip"
          title="Session Labels"
          placement="bottom"
        >
          <LabelContainer>
            <LabelsIcon />
            Labels 
            <Badge count={labelSession?.length || 0} />
          </LabelContainer>
        </Tooltip>
      </span>
    </HeaderItem>
  );
};

export const IssueInfoComponent: React.FC<IssueInfoComponentProps> = ({ 
  isCrashLog, 
  totalBugs, 
  anrMenu 
}) => {
  if (!isCrashLog && !totalBugs?.length && !anrMenu?.length) return null;
  
  return (
    <HeaderItem value={Boolean(totalBugs?.length > 0 && anrMenu?.length)}>
      <IssueInfo
        isCrashLog={isCrashLog}
        totalBugs={totalBugs}
        anrMenu={anrMenu}
      />
    </HeaderItem>
  );
}; 